"""Build docs/spike_report.md tables from results/spike/spike_raw.jsonl (no hand-typed figures)."""
import json
from pathlib import Path

ROOT = Path(__file__).resolve().parent.parent
rows = [json.loads(l) for l in (ROOT / "results/spike/spike_raw.jsonl").read_text().splitlines() if l.strip()]
GB = 1e9
WINDOW_DAYS = 396          # 2025-10-01..2026-10-31 inclusive: 365 + 31 (verified by script below)
PAIRS = 6
BUDGET_S = 7 * 3600

from datetime import date
assert (date(2026, 10, 31) - date(2025, 10, 1)).days + 1 == WINDOW_DAYS

out = ["# Phase 1 spike report", "",
       "Generated by scripts/make_spike_report.py from results/spike/spike_raw.jsonl. Input: Kronos example CSV only; "
       "no forecast accuracy was computed. Model in eval() mode for all timings (after `from_pretrained` both objects reported training=True).",
       "", "## Timing and memory (lookback 512, pred_len 24, T=1.0, top_p=0.9, 1 warm-up excluded + 3 repeats, median)", "",
       "| device | config | sample_count | batch | shape/NaN ok | warm-up s | timed s | median s/call | median s/origin | peak RSS (time -l) GB | peak footprint GB | note |",
       "|---|---|---|---|---|---|---|---|---|---|---|---|"]
timing = [r for r in rows if "sample_count" in r or r.get("error") or r.get("aborted")]
for r in timing:
    if r.get("cfg") in ("DET", "PARITY", "MODECMP"):
        continue
    note = r.get("error") or r.get("aborted") or r.get("skipped_repeats") or ""
    f = lambda v, n=2: "NA" if v is None else f"{v:.{n}f}"
    out.append("| {d} | {c} | {s} | {b} | {ok} | {w} | {t} | {m} | {o} | {rss} | {fp} | {n} |".format(
        d=r["device"], c=r["cfg"], s=r.get("sample_count", ""), b=r.get("batch", ""),
        ok=f"{r.get('shape_ok')}/{r.get('nan_free')}", w=f(r.get("warmup_sec")),
        t=", ".join(f"{x:.2f}" for x in r.get("timed_sec", [])), m=f(r.get("median_sec_per_call")),
        o=f(r.get("median_sec_per_origin")), rss=f(r.get("maxrss_bytes_time_l", 0) / GB, 3),
        fp=f(r.get("peak_footprint_bytes_time_l", 0) / GB, 3), n=note))

out += ["", "IND11 = 11 independent sample_count=1 calls per origin (seeds 1000+100r+j); its 'call' is the 11-call unit; warm-up is one single call.",
        "The 120 s rule is applied to the whole timed unit. Peak RSS = `/usr/bin/time -l` maximum resident set size of the whole process (includes model load).", ""]

out += ["## Determinism (same torch.manual_seed(777) twice, S=5, in one process)", "",
        "| device | identical | max abs diff | differs with seed 778 | NaN-free | output sha256[:16] |", "|---|---|---|---|---|---|"]
for r in rows:
    if r.get("cfg") == "DET":
        out.append(f"| {r['device']} | {r.get('identical_same_seed')} | {r.get('max_abs_diff_same_seed')} | {r.get('differs_other_seed')} | {r.get('nan_free')} | {r.get('sha256_seed777')} |" if "error" not in r else f"| {r['device']} | ERROR: {r['error']} | | | | |")

out += ["", "## Wrapper parity (kronos_lab.sampling vs original predict, same seed; tolerance in tests: rtol=1e-5, atol=1e-5)", "",
        "| device | S | max abs diff | max rel diff | samples shape |", "|---|---|---|---|---|"]
for r in rows:
    if r.get("cfg") == "PARITY":
        for p in r.get("parity", []):
            out.append(f"| {r['device']} | {p['S']} | {p['max_abs']} | {p['max_rel']:.3g} | {p['samples_shape']} |")
        if "error" in r:
            out.append(f"| {r['device']} | ERROR: {r['error']} | | | |")

out += ["", "## eval vs train mode (one S=1 forecast; forecast-to-forecast differences only, NO comparison with realised prices)", "",
        "| device | shapes ok | NaN-free | mean |diff| OHLC eval vs train (same seed) | mean |diff| OHLC eval vs eval (other seed) | % of mean context close (eval-vs-train / eval-vs-eval) |", "|---|---|---|---|---|---|"]
for r in rows:
    if r.get("cfg") == "MODECMP":
        if "error" in r:
            out.append(f"| {r['device']} | ERROR: {r['error']} | | | | |"); continue
        out.append(f"| {r['device']} | {r['shapes_ok']} | {r['nan_free']} | {r['mean_abs_diff_ohlc_eval_vs_train_same_seed']:.4f} | "
                   f"{r['mean_abs_diff_ohlc_eval_vs_eval_other_seed']:.4f} | {r['pct_of_mean_close_eval_vs_train']:.3f} / {r['pct_of_mean_close_eval_vs_eval_other_seed']:.3f} |")

# Sizing
out += ["", "## Sizing (no decisions)", "",
        f"Window 2025-10-01..2026-10-31 UTC = {WINDOW_DAYS} days (365 + 31, asserted in code). One origin per day at 00:00 UTC, "
        f"forecast bars = the 24 hourly bars of that day, so the last origin (2026-10-31 00:00) labels end 2026-10-31 23:00, inside the window: {WINDOW_DAYS} origins/pair "
        f"(395 if the origin bar itself must be inside the window and the forecast starts one bar later). Context (512 bars) precedes the window and is input only. "
        f"Budget {BUDGET_S/3600:.0f} h = {BUDGET_S} s.", ""]
best = {}
for r in timing:
    if r.get("median_sec_per_origin") is not None:
        k = (r["device"], r["sample_count"])
        if k not in best or r["median_sec_per_origin"] < best[k][0]:
            best[k] = (r["median_sec_per_origin"], r["cfg"])
out += ["| device | sample_count | best config | s/origin | max origins in 7 h | A: 6x396=2376 h | B: 6x198=1188 h | C: 6x66=396 h |", "|---|---|---|---|---|---|---|---|"]
for (d, s), (sec, cfg) in sorted(best.items()):
    out.append(f"| {d} | {s} | {cfg} | {sec:.2f} | {int(BUDGET_S // sec)} | {2376*sec/3600:.2f} | {1188*sec/3600:.2f} | {396*sec/3600:.2f} |")
out += ["", "B = every 2nd day; C = every 6th day (illustrative reduced/minimum sizes, not recommendations).", ""]
import hashlib

# Weights provenance: local sha256 of the cached blobs vs HF ?blobs=true; last commit that changed model.safetensors
out += ["## Weights provenance", "",
        "| model | local sha256 | HF lfs sha256 | match | last commit changing model.safetensors (tree?expand=true) | repo lastModified |", "|---|---|---|---|---|---|"]
for m in ("Kronos-small", "Kronos-Tokenizer-base"):
    prov = ROOT / "docs/provenance"
    blobs = json.loads((prov / f"hf_{m}_blobs.json").read_text())
    remote = next(s["lfs"]["sha256"] for s in blobs["siblings"] if s["rfilename"] == "model.safetensors")
    blob = ROOT / f".cache/huggingface/hub/models--NeoQuasar--{m}/blobs/{remote}"
    local = hashlib.sha256(blob.read_bytes()).hexdigest()
    tree_name = "hf_Kronos-small_tree_main_expand.json" if m == "Kronos-small" else "hf_Kronos-Tokenizer-base_tree_main_expand.json"
    lc = next(x["lastCommit"] for x in json.loads((prov / tree_name).read_text()) if x["path"] == "model.safetensors")
    out.append(f"| {m} | {local[:16]}... | {remote[:16]}... | {local == remote} | {lc['id'][:8]} {lc['date']} ({lc['title']}) | {blobs.get('lastModified')} |")
out += ["", "## Seed convention", "",
        "`torch.manual_seed(seed)` immediately before every forecast call (seeds CPU and MPS). Spike: warm-up seed 0; timed repeat r seed 1000+r; "
        "IND11 unit r uses 1000+100r+j. Proposed for the real run: seed = 1_000_000 * pair_index + origin_index (one seed per origin).", ""]
(ROOT / "docs/spike_report.md").write_text("\n".join(out) + "\n")
print("\n".join(out))
